DEFERRED={'sanitarian':'较专门的公共卫生从业者名称，先学 sanitation、sanitary。','summa cum laude':'拉丁荣誉等级短语，本轮单词词族先略过。','deploration':'低频哀叹名词，优先 deplore、deplorable。','imploration':'低频恳求名词，优先 implore。','imploratory':'罕用形容词，优先 imploring。'}
PORT_ROOT=dict(id='C1106',meaning='份额、部分；比例与分配',core='把整体分成几份，再比较各份有多大、每个人该得多少。',image='拉丁 portio 份额 → portion；pro portione 按各部分的关系 → proportio → proportion；按份分配 → apportion；相称 → proportionate。',intro='portion 指其中的一份，proportion 关心这一份与整体或另一份的关系。proportional、proportionate 各有古典借入历史；相似词尾只是今天的记忆线索。apportion 经法语形成，不把开头 a- 当英语冠词。',forms='proportionate 形容词尾音 /ət/；proportionately 保留这个音，proportionally 则来自 proportional。disproportion 与 disproportionate 都说失衡，但名词、形容词作用不同。',branches=[['一份与比例','portion, proportion'],['相称、按比例变化','proportionate, proportionately, proportional, proportionally'],['比例失衡','disproportion, disproportionate, disproportionately'],['分配份额与责任','apportion, apportionment']],contrasts='portion 是一份，proportion 是相对大小。proportional 不只是两件事一起增长；严格数学关系要看比例。apportion 不保证平均，disproportionate 也不是单纯数量大。',practice='用 portion 描述一份食物，用 proportion 说某类人所占比例；解释 equally 与 proportionately 分配可能为什么得到不同结果。',words=[w for w in ASSIGN['roots'][79]['family'] if w not in DEFERRED],exclude={})
SAN_ROOT=dict(id='C1253',meaning='健康、健全；理智与卫生',core='让身体、头脑或生活环境处在能够正常运作的状态。',image='拉丁 sanus 健全 → sanitas；sanity 走向理智，sanitaire → sanitary 走向卫生；sanare 治疗 → sanatorium。sane 的心智义也可能受 sanity / insane 反构影响。',intro='san- 在这里是健康、健全，不是 sanc- 神圣那个词根。sanity 在英语里比 sane 更早；insane 也有独立拉丁借词历史，不能见到否定前缀就断定英语一定先有肯定词。sanitary、sanitation、sanitize 则以卫生条件为中心。',forms='sane /seɪn/ 与 sanity /ˈsænəti/ 的元音不同。sanitation 来自 sanitary 的词干构造，sanitize 则加 -ize；sanitization 是卫生处理过程，不等于整个公共卫生系统。sanatorium 有长期疗养的历史语境。',branches=[['理智与夸张的日常说法','sane, sanely, sanity, insane, insanity, insanely'],['卫生环境和公共服务','sanitary, unsanitary, sanitation'],['卫生处理及粉饰引申义','sanitize, sanitizer, sanitization, sanitized'],['长期治疗、疗养场所','sanatorium']],contrasts='sanity 是理智，sanitation 是公共卫生。sanitize 不等于完全灭菌；sanitized version 也可能是在说粉饰。sane、insane 的日常夸张不能直接当临床判断。',practice='分别用 sanitary、sanity 描述厨房条件和繁忙生活里的理智；解释 sanitized version 为什么可以指一段经过粉饰的故事。',words=[w for w in ASSIGN['roots'][80]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][80]['family'] if w in DEFERRED})
SUM_ROOT=dict(id='C1453',meaning='最高；总体、总额；要点与完成',core='把散开的数量或内容收在一起，得到一个总数、一包要点，或最终完成的整体。',image='拉丁 summus 最高 → summa 顶端、总额、要点 → sum；summarius / summarium → summary；con- + summa → consummare 完成 → consummate / consummation。',intro='这组主线是拉丁 summa、summus。由最高到总额的历史常被联系到古代账目把总数写在上方，但这只是提出过的解释，不需要靠它才能理解现代词义。sum 与 summary 分别收拢数量、内容；consummate 则强调完整完成。',forms='sum 动词也有法语、拉丁借入背景。summary 的形容词与名词分别接 summarius、summarium；summation 和 consummation 也有独立拉丁名词链。summarily 常说直接处理，不能随便代替 in summary。',branches=[['总数、金额与求和','sum, summation'],['摘要与概括','summary, summarize, summarization'],['简略而直接的处置','summarily'],['完成与圆满','consummate, consummation'],['最高处与峰会〔共享词〕','summit']],contrasts='sum 与 some 同音但意思不同；summon 属于提醒、召唤词族。consummate 不是 consume 的变体。summary 可作摘要名词，也可修饰直接、简易进行的处理。',practice='分别用 sum、summary 概括一串数字和一篇报告；比较 in summary 与 summarily；读出 consummate 形容词与动词的词尾差别。',words=[w for w in ASSIGN['roots'][81]['family'] if w not in DEFERRED],exclude={'summa cum laude':DEFERRED['summa cum laude']})
PLOR_ROOT=dict(id='C1074',meaning='哭泣、呼喊；恳求、痛惜与探查',core='哭喊可以是请求帮助，也可以是对糟糕事情的哀叹；探索支线的呼喊解释则应保留不确定性。',image='plorare 哭喊 → implorare 向人呼求 → implore；deplorare 深切哀叹 → deplore。explorare 调查常联系 ex- + plorare，但不是已定论的起源。',intro='implore、deplore 可以清楚接回拉丁 plorare。explore 的确定起点是 explorare 调查、搜寻；传统解释设想猎人喊叫来探查猎物，但也有其他来源分析，正文不把这个故事写成事实。知道不确定边界，比硬把三个词都翻成哭更有用。',forms='exploration 和 exploratory 在英语里都早于 explore，分别有拉丁名词、形容词借入路线；explorer 才是在英语里由 explore 加 -er。deplorable 可按现代 deplore + -able 记忆，也有法语、拉丁借词背景。',branches=[['探索地方、想法与可能性','explore, exploration, explorer, exploratory, unexplored'],['痛惜与强烈不赞成','deplore, deplorable, deplorably'],['急切恳求','implore, imploring']],contrasts='explore 是探索过程，discover 是发现结果。deplore 强烈不赞成或痛惜，implore 则是请求对方做事。exploratory 说先行摸索，不表示结论已证实。',practice='用 explore、exploratory 描述一次初步研究；分别用 deplore、implore 说明谴责某个行为和恳求某人不要做某事。',words=[w for w in ASSIGN['roots'][82]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][82]['family'] if w in DEFERRED})
